    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private void buttons(){auto.setEnabled(!capturing&&!closing);shutter.setEnabled(!closing&&docReady&&active&&camera!=null&&session!=null&&!capturing&&pages<DocumentStore.MAX_PAGES);done.setEnabled(docReady&&!capturing&&!closing);done.setText(dev.pocketllama.I18n.t("Готово · ")+pages);flash.setEnabled(hasFlash&&camera!=null&&!capturing);}
